CREATE TABLE users (user_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, full_name VARCHAR(120) NOT NULL, email VARCHAR(150) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, role VARCHAR(20) NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE assets (asset_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, asset_name VARCHAR(150) NOT NULL, asset_value DECIMAL(18,2) NOT NULL, principal_amount DECIMAL(18,2) NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE liabilities (liability_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, liability_name VARCHAR(150) NOT NULL, liability_value DECIMAL(18,2) NOT NULL, principal_amount DECIMAL(18,2) NOT NULL, status VARCHAR(20) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE scenarios (scenario_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, scenario_name VARCHAR(150) NOT NULL, scenario_type VARCHAR(30) NOT NULL, interest_rate_shock DECIMAL(8,4) NOT NULL DEFAULT 0, status VARCHAR(20) NOT NULL, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL);
CREATE TABLE scenario_results (result_id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY, scenario_id BIGINT NOT NULL, asset_impact DECIMAL(18,2) NOT NULL DEFAULT 0, liability_impact DECIMAL(18,2) NOT NULL DEFAULT 0, net_impact DECIMAL(18,2) NOT NULL DEFAULT 0, risk_level VARCHAR(15) NOT NULL, calculated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP NOT NULL, FOREIGN KEY (scenario_id) REFERENCES scenarios(scenario_id) ON DELETE CASCADE);
